<?php/** * Legacy Archive Tab — View Only * * All logic is handled by includes/Archive.php * * @package MegaGovern * @since   1.0.4 * @var array $args */if ( ! defined( 'ABSPATH' ) ) {    exit;}use MegaGovern\Archive;// ─── Handle Settings Save ───if ( isset( $_POST['mg_save_cutoff'] ) && check_admin_referer( 'mg_legacy_cutoff_nonce' ) ) {    if ( current_user_can( 'manage_options' ) ) {        if ( isset( $_POST['mg_cutoff_date'] ) ) {            Archive::save_cutoff_date( sanitize_text_field( wp_unslash( $_POST['mg_cutoff_date'] ) ) );        }        if ( isset( $_POST['mg_edit_threshold'] ) ) {            Archive::save_edit_threshold( (int) $_POST['mg_edit_threshold'] );        }        echo '<div class="notice notice-success"><p>' . esc_html__( 'Settings saved.', 'megagovern' ) . '</p></div>';    }}// ─── Get Data from Logic Layer ───$megagovern_cutoff_date      = Archive::get_cutoff_date();$megagovern_edit_threshold   = Archive::get_edit_threshold();// Use count method for performance, then get paginated results$megagovern_total_legacy     = Archive::count_legacy_content();$megagovern_legacy_query     = Archive::get_legacy_query( [ 'paged' => $args['paged'] ?? 1 ] );$megagovern_exempt_posts     = Archive::get_exempt_posts( 10 );$megagovern_total_exempt     = Archive::count_exempt_posts();$megagovern_formatted_date   = Archive::get_formatted_cutoff_date();$megagovern_days_ago         = Archive::days_since_cutoff();// ─── Passed from parent ───$megagovern_stats          = $args['stats']          ?? [];$megagovern_registry_total = $args['registry_total'] ?? 0;$megagovern_registry_last  = $args['registry_last']  ?? __( 'Active', 'megagovern' );$megagovern_is_free        = $args['is_free']        ?? true;$megagovern_has_pro        = $args['has_pro']        ?? false;$megagovern_is_agency      = $args['is_agency']      ?? false;$megagovern_upgrade_url    = $args['upgrade_url']    ?? '';$megagovern_paged          = $a