ue,        ),        'polygon' => array(            'points' => true,            'fill' => true,            'stroke' => true,        ),    );}$megagovern_allowed_svg = megagovern_get_allowed_svg_html();?><div class="mga-archive-wrap">    <!-- HEADER -->    <div class="mga-section">        <div class="mga-section-header">            <h2 class="mga-section-title"><?php echo wp_kses( megagovern_get_icon( 'archive', '20' ), $megagovern_allowed_svg ); ?> <?php esc_html_e( 'Legacy Archive', 'megagovern' ); ?></h2>            <p class="mga-section-desc">                <?php esc_html_e( 'Historical content published before the cutoff date. Classified as Legacy — Exempt from mandatory AI declaration under EU AI Act Article 50.', 'megagovern' ); ?>            </p>        </div>    </div>    <!-- UPGRADE BANNER (FREE ONLY) -->    <?php if ( $megagovern_is_free && $megagovern_upgrade_url ) : ?>    <div class="mga-card" style="margin-bottom: 16px;">        <div class="mga-card-upgrade" style="display: flex; align-items: center; gap: 12px; flex: 1;">            <?php echo wp_kses( megagovern_get_icon( 'trending-up', '18' ), $megagovern_allowed_svg ); ?>            <div>                <strong><?php esc_html_e( 'Unlock Full Archive Management', 'megagovern' ); ?></strong>                <span style="display: block; font-size: 12px; color: #646970;"><?php esc_html_e( 'Advanced filtering, bulk exemption, and audit trail for legacy content.', 'megagovern' ); ?></span>            </div>        </div>        <a href="<?php echo esc_url( $megagovern_upgrade_url ); ?>" class="button button-primary button-small">            <?php esc_html_e( 'Upgrade to Pro', 'megagovern' ); ?>        </a>    </div>    <?php endif; ?>    <!-- EU AI ACT NOTICE -->    <div class="mga-card" style="margin-bottom: 16px; background: #fef2f2; border-color: #d63638;">        <div class="mga-card-body" style="display: flex; align-items: flex-start; gap: 12px;">         