y" style="text-align: center;">                <div style="font-size: 28px; font-weight: 700; color: #646970;"><?php echo esc_html( $megagovern_edit_threshold ); ?>%</div>                <div class="mga-card-text"><?php esc_html_e( 'Edit Threshold', 'megagovern' ); ?></div>            </div>        </div>    </div>    <!-- SETTINGS: CUTOFF DATE + THRESHOLD -->    <div class="mga-card" style="margin-bottom: 16px;">        <div class="mga-card-header">            <h3 class="mga-card-title"><?php echo wp_kses( megagovern_get_icon( 'sliders', '16' ), $megagovern_allowed_svg ); ?> <?php esc_html_e( 'Archive Settings', 'megagovern' ); ?></h3>        </div>        <div class="mga-card-body">            <form method="post" style="display: flex; gap: 24px; flex-wrap: wrap; align-items: flex-end;">                <?php wp_nonce_field( 'mg_legacy_cutoff_nonce' ); ?>                <div>                    <label for="mg_cutoff_date" style="display: block; font-weight: 600; margin-bottom: 4px;">                        <?php esc_html_e( 'Compliance Cutoff Date', 'megagovern' ); ?>                    </label>                    <input type="date" id="mg_cutoff_date" name="mg_cutoff_date" value="<?php echo esc_attr( $megagovern_cutoff_date ); ?>" class="regular-text" style="width: 180px;">                    <p class="mga-card-text" style="margin: 4px 0 0;"><?php esc_html_e( 'Content before this date is exempt.', 'megagovern' ); ?></p>                </div>                <div>                    <label for="mg_edit_threshold" style="display: block; font-weight: 600; margin-bottom: 4px;">                        <?php esc_html_e( 'Edit Threshold (%)', 'megagovern' ); ?>                    </label>                    <input type="number" id="mg_edit_threshold" name="mg_edit_threshold" value="<?php echo esc_attr( $megagovern_edit_threshold ); ?>" min="0" max="100" class="small-text" style="width: 80px;">                    <p class="mga-card-text" style="ma