                  </span>                        </td>                        <td>                            <?php if ( ! $megagovern_revoked ) : ?>                                <button type="button" class="button button-small button-secondary mga-revoke-exempt" data-post="<?php echo esc_attr( $megagovern_post->ID ); ?>" data-nonce="<?php echo esc_attr( $megagovern_nonce_archive ); ?>">                                    <?php echo wp_kses( megagovern_get_icon( 'x-circle', '12' ), $megagovern_allowed_svg ); ?>                                    <?php esc_html_e( 'Revoke', 'megagovern' ); ?>                                </button>                            <?php else : ?>                                <button type="button" class="button button-small mga-restore-exempt" data-post="<?php echo esc_attr( $megagovern_post->ID ); ?>" data-nonce="<?php echo esc_attr( $megagovern_nonce_archive ); ?>">                                    <?php echo wp_kses( megagovern_get_icon( 'check-circle', '12' ), $megagovern_allowed_svg ); ?>                                    <?php esc_html_e( 'Restore', 'megagovern' ); ?>                                </button>                            <?php endif; ?>                        </td>                    </tr>                    <?php endforeach; ?>                </tbody>            </table>        </div>                <!-- Pagination -->        <?php if ( $megagovern_legacy_query->max_num_pages > 1 ) : ?>        <div class="mga-pagination" style="margin: 16px; text-align: center;">            <?php            echo wp_kses_post( paginate_links( [                'total'     => $megagovern_legacy_query->max_num_pages,                'current'   => $megagovern_paged,                'format'    => '?paged=%#%',                'prev_text' => '&laquo;',                'next_text' => '&raquo;',            ] ) );            ?>        </div>        <?php endif; ?>                <?php else : ?>        <div class="mga-card-body" style="text-align: center; padding: 40px;">            <?php echo wp_kses( megagovern_get_icon( 'check-circle', '32' ), $megagovern_allowed_svg ); ?>            <p style="margin-top: 12px; color: #646970;"><?php esc_html_e( 'No exempt content found. Content published after the cutoff date will not be automatically exempt.', 'megagovern' ); ?></p>        </div>        <?php endif; ?>    </div>    <!-- HOW IT WORKS -->    <div class="mga-card" style="background: #f0f6fc; border-color: #c3c4c7; margin-bottom: 16px;">        <div class="mga-card-header">            <h3 class="mga-card-title"><?php echo wp_kses( megagovern_get_icon( 'help-circle', '16' ), $megagovern_allowed_svg ); ?> <?php esc_html_e( 'How Legacy Archive Works', 'megagovern' ); ?></h3>        </div>        <div class="mga-card-body">            <div style="display: flex; flex-direction: column; gap: 16px;">                <div style="display: flex; gap: 12px;">                    <span style="width: 24px; height: 24px; border-radius: 50%; background: #2271b1; color: #fff; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; flex-shrink: 0;">1</span>                    <div>                        <strong><?php esc_html_e( 'Set Cutoff Date', 'megagovern' ); ?></strong>                        <p class="mga-card-text" style="margin: 2px 0 0;"><?php esc_html_e( 'Define the compliance cutoff date. Content published before this date is eligible for legacy exemption.', 'megagovern' ); ?></p>                    </div>                </div>                <div style="display: flex; gap: 12px;">                    <span style="width: 24px; height: 24px; border-radius: 50%; background: #2271b1; color: #fff; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; flex-shrink: 0;">2</span>                    <div>                        <strong><?php esc_html_e( 'Edit Threshold Monitoring', 'megagovern' ); ?></strong>                        <p class="mga-card-text" style="margin: 2px 0 0;"><?php esc_html_e( 'If an exempt article is edited and changes exceed the threshold, the exemption is automatically revoked.', 'megagovern' ); ?></p>                    </div>                </div>                <div style="display: flex; gap: 12px;">                    <span style="width: 24px; height: 24px; border-radius: 50%; background: #2271b1; color: #fff; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; flex-shrink: 0;">3</span>                    <div>                        <strong><?php esc_html_e( 'Manual Override', 'megagovern' ); ?></strong>                        <p class="mga-card-text" style="margin: 2px 0 0;"><?php esc_html_e( 'You can manually revoke or restore exemptions from the Exempt Content Log above.', 'megagovern' ); ?></p>                    </div>                </div>            </div>        </div>    </div></div><!-- JAVASCRIPT --><script>(function($) {    'use strict';    $(document).ready(function() {        // Revoke exemption.        $('.mga-revoke-exempt').on('click', function() {            var $btn = $(this);            var postId = $btn.data('post');            var nonce = $btn.data('nonce');            if (!postId) return;            if (!confirm('<?php echo esc_js( __( 'Are you sure you want to revoke this exemption? The post will return to the Content Hub for standard declaration.', 'megagovern' ) ); ?>')) return;            $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Processing...', 'megagovern' ) ); ?>');            $.ajax({                url: window.ajaxurl || '/wp-admin/admin-ajax.php',                type: 'POST',                data: {                    action: 'megagovern_revoke_exemption',                    post_id: postId,                    nonce: nonce                },                success: function(response) {                    if (response.success) {                        $btn.closest('tr').fadeOut(300, function() {                            $(this).remove();                            location.reload();                        });                    } else {                        alert(response.data?.message || '<?php echo esc_js( __( 'Failed to revoke exemption.', 'megagovern' ) ); ?>');                        $btn.prop('disabled', false).text('<?php echo esc_js( __( 'Revoke', 'megagovern' ) ); ?>');                    }                },                error: function() {                    alert('<?php echo esc_js( __( 'An error occurred. Please try again.', 'megagovern' ) ); ?>');                    $btn.prop('disabled', false).text('<?php echo esc_js( __( 'Revoke', 'megagovern' ) ); ?>');                }            });        });        // Restore exemption.        $('.mga-restore-exempt').on('click', function() {            var $btn = $(this);            var postId = $btn.data('post');            var nonce = $btn.data('nonce');            if (!postId) return;            $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Processing...', 'megagovern' ) ); ?>');            $.ajax({                url: window.ajaxurl || '/wp-admin/admin-ajax.php',                type: 'POST',                data: {                    action: 'megagovern_restore_exemption',                    post_id: postId,                    nonce: nonce                },                success: function(response) {                    if (response.success) {                        location.reload();                    } else {                        alert(response.data?.message || '<?php echo esc_js( __( 'Failed to restore exemption.', 'megagovern' ) ); ?>');                        $btn.prop('disabled', false).text('<?php echo esc_js( __( 'Restore', 'megagovern' ) ); ?>');                    }                },                error: function() {                    alert('<?php echo esc_js( __( 'An error occurred. Please try again.', 'megagovern' ) ); ?>');                    $btn.prop('disabled', false).text('<?php echo esc_js( __( 'Restore', 'megagovern' ) ); ?>');                }            });        });    });})(jQuery);</script>